Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â combines list + form in one view.
    /// Swaps between list view and edit view without any popup.
    /// </summary>
    public class CustomersView : UserControl
    {
        private readonly CustomerApiService _customerService = new();

        // Containers
        private Panel pnlListContainer = null!;
        private Panel pnlEditContainer = null!;
        private Panel pnlDetailContainer = null!;
        private int _activeCustomerId = 0;
        private Panel pnlInteractionDetailContainer = null!;

        // List controls
        private TextBox txtSearch = null!;
        private ComboBox cmbType = null!;
        private ComboBox cmbActive = null!;
        private CheckBox chkShowArchived = null!;
        private Button btnSearch = null!;
        private FloatingActionButton fabNew = null!;
        private Button btnRefresh = null!;
        private FlowLayoutPanel pnlCards = null!;

        // State

        public CustomersView()
        {
            InitializeComponent();
            Load += async (s, e) => await LoadDataAsync();
        }

        private void InitializeComponent()
        {
            Dock = DockStyle.Fill;
            BackColor = Theme.BackgroundColor;

            // ============================================
            // EDIT CONTAINER (hidden by default)
            // ============================================
            pnlEditContainer = new Panel
            {
                Dock = DockStyle.Fill,
                BackColor = Color.White,
                Visible = false
            };

            pnlDetailContainer = new Panel
            {
                Dock = DockStyle.Fill,
                BackColor = Colors.Background,
                Visible = false
            };

            pnlInteractionDetailContainer = new Panel
            {
                Dock = DockStyle.Fill,
                BackColor = Colors.Background,
                Visible = false
            };

            // ============================================
            // LIST CONTAINER
            // ============================================
            pnlListContainer = new Panel
            {
                Dock = DockStyle.Fill,
                BackColor = Theme.BackgroundColor
            };

            // ============================================
            // ============ FILTER PANEL ============
            var pnlFilter = new Panel
            {
                Dock = DockStyle.Top,
                Height = 74,
                BackColor = Colors.Surface,
                Padding = new Padding(24, 12, 24, 12)
            };
            pnlFilter.Paint += (s, e) =>
            {
                using var pen = new Pen(Colors.Border, 1f);
                e.Graphics.DrawLine(pen, 0, pnlFilter.Height - 1, pnlFilter.Width, pnlFilter.Height - 1);
            };

            var lblSearch = new Label
            {
                Text = "Search",
                Font = Typography.Small,
                ForeColor = Colors.TextSecondary,
                Location = new Point(24, 8),
                AutoSize = true
            };
            txtSearch = new TextBox
            {
                Location = new Point(24, 28),
                Width = 260,
                Font = Typography.Body,
                BorderStyle = BorderStyle.FixedSingle
            };
            txtSearch.KeyPress += async (s, e) => { if (e.KeyChar == (char)Keys.Enter) await SearchAsync(); };
            pnlFilter.Controls.Add(txtSearch);

            var lblType = new Label
            {
                Text = "Type",
                Font = Typography.Small,
                ForeColor = Colors.TextSecondary,
                Location = new Point(300, 8),
                AutoSize = true
            };
            cmbType = new ComboBox
            {
                Location = new Point(300, 28),
                Width = 130,
                Font = Typography.Body,
                DropDownStyle = ComboBoxStyle.DropDownList
            };
            cmbType.Items.AddRange(new object[] { "All", "Individual", "Business" });
            cmbType.SelectedIndex = 0;
            cmbType.SelectedIndexChanged += async (s, e) => await SearchAsync();
            pnlFilter.Controls.Add(cmbType);

            var lblActive = new Label
            {
                Text = "Status",
                Font = Typography.Small,
                ForeColor = Colors.TextSecondary,
                Location = new Point(446, 8),
                AutoSize = true
            };
            cmbActive = new ComboBox
            {
                Location = new Point(446, 28),
                Width = 120,
                Font = Typography.Body,
                DropDownStyle = ComboBoxStyle.DropDownList
            };
            cmbActive.Items.AddRange(new object[] { "All", "Active", "Inactive" });
            cmbActive.SelectedIndex = 0;
            cmbActive.SelectedIndexChanged += async (s, e) => await SearchAsync();
            pnlFilter.Controls.Add(cmbActive);

            chkShowArchived = new CheckBox
            {
                Text = "Show Archived",
                Font = Typography.Small,
                ForeColor = Colors.TextSecondary,
                Location = new Point(800, 31),
                AutoSize = true,
                Cursor = Cursors.Hand
            };
            chkShowArchived.CheckedChanged += async (s, e) => await SearchAsync();
            pnlFilter.Controls.Add(chkShowArchived);

            btnSearch = new Button
            {
                Text = "Search",
                Location = new Point(586, 26),
                Width = 90,
                Height = 32
            };
            Theme.StylePrimaryButton(btnSearch);
            btnSearch.Click += async (s, e) => await SearchAsync();
            pnlFilter.Controls.Add(btnSearch);

            btnRefresh = new Button
            {
                Text = "Refresh",
                Location = new Point(686, 26),
                Width = 90,
                Height = 32
            };
            Theme.StyleSecondaryButton(btnRefresh);
            btnRefresh.Click += async (s, e) => await LoadDataAsync();
            pnlFilter.Controls.Add(btnRefresh);

            pnlFilter.Controls.AddRange(new Control[] { lblSearch, lblType, lblActive });
            // ============================================
            // ============================================
            // DATAGRIDVIEW
            // DATAGRIDVIEW
            // ============================================
            pnlCards = new FlowLayoutPanel
            {
                Dock = DockStyle.Fill,
                AutoScroll = true,
                FlowDirection = FlowDirection.TopDown,
                WrapContents = false,
                BackColor = Colors.Background,
                Padding = new Padding(24, 16, 24, 88)
            };
            pnlCards.Resize += (s, e) => ResizeCards();
            
            // Create FAB (Floating Action Button) - New Customer
            fabNew = new FloatingActionButton
            {
                NormalColor  = Colors.Primary,
                HoverColor   = Colors.PrimaryHover,
                PressedColor = Colors.PrimaryActive,
                GlyphColor   = Color.White,
                Visible      = false   // gated by ApplyPermissionGates()
            };
            fabNew.Click += (s, e) => OpenEditView(0);

            // Add controls in correct dock order:
            //   1. Fill  (bottom of z-order - takes remaining space)
            //   2. Top   (docks to top edge)
            //   3. Manual (FAB - absolute positioned)
            pnlListContainer.Controls.Add(pnlCards);
            pnlListContainer.Controls.Add(pnlFilter);
            pnlListContainer.Controls.Add(fabNew);
            fabNew.BringToFront();
            fabNew.PinToParentBottomRight();

            // ============================================
            // ASSEMBLE VIEW
            // ============================================
            Controls.Add(pnlEditContainer);
            Controls.Add(pnlInteractionDetailContainer);
            Controls.Add(pnlDetailContainer);
            Controls.Add(pnlListContainer);

        }

        // ============================================
        // VIEW SWITCHING
        // ============================================
        private async void OpenDetailView(int customerId, string initialTab = "profile")
        {
            var response = await _customerService.GetCustomersAsync(
                page: 1,
                pageSize: 10000,
                search: null,
                customerType: null,
                isActive: null);

            var customer = response.Data.Find(c => c.CustomerId == customerId);
            if (customer == null)
            {
                MessageBox.Show($"Customer {customerId} not found.", "Error",
                    MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            _activeCustomerId = customerId;
            pnlInteractionDetailContainer.Visible = false;
            pnlDetailContainer.Controls.Clear();

            var detail = new CustomerDetailPanel(customerId)
            {
                InitialTab      = initialTab,
                CustomerName    = customer.FullName ?? "",
                CustomerCode    = customer.CustomerCode ?? "",
                CustomerType    = customer.CustomerType ?? "",
                Email           = customer.Email ?? "",
                PhonePrimary    = customer.PhonePrimary ?? "",
                Street          = customer.Street ?? "",
                Village         = customer.Village ?? "",
                City            = customer.City ?? "",
                State           = customer.State ?? "",
                PostalCode      = customer.PostalCode ?? "",
                Country         = customer.Country ?? "",
                Notes           = customer.Notes ?? "",
                LoyaltyPoints   = customer.LoyaltyPoints,
                LifetimeSpend   = customer.LifetimeSpend,
                TotalOrders     = customer.TotalOrders,
                LastOrderDate   = customer.LastOrderDate,
                CreatedAt       = customer.CreatedAt,
                IsActive        = customer.IsActive
            };

            detail.EditRequested += (s, id) => OpenEditView(id);
            detail.BackRequested += (s, e) => ShowListView();

            pnlDetailContainer.Controls.Add(detail);

            pnlListContainer.Visible = false;
            pnlEditContainer.Visible = false;
            pnlDetailContainer.Visible = true;
            pnlDetailContainer.BringToFront();
        }
        private void OpenEditView(int customerId)
        {
            pnlEditContainer.Controls.Clear();

            var editPanel = new CustomerEditPanel(customerId);
            editPanel.Saved += (s, e) =>
            {
                ShowListView();
                _ = LoadDataAsync();
            };
            editPanel.Cancelled += (s, e) => ShowListView();

            editPanel.Dock = DockStyle.Fill;
            pnlEditContainer.Controls.Add(editPanel);

            pnlListContainer.Visible = false;
            pnlEditContainer.Visible = true;
            pnlEditContainer.BringToFront();
        }

        protected override void OnLoad(EventArgs e)
        {
            base.OnLoad(e);
            if (fabNew != null && fabNew.Parent != null)
                fabNew.PinToParentBottomRight();

            ApplyPermissionGates();
        }

        public void ShowInteractionDetail(CRM.WinForms.Models.CustomerInteractionModel interaction)
        {
            pnlInteractionDetailContainer.Controls.Clear();

            var api = new CRM.WinForms.Services.CustomerInteractionApiService(
                CRM.WinForms.Services.ApiClient.Instance);

            var panel = new CRM.UI.Controls.CustomerInteractionDetailPanel(interaction, api);
            panel.BackRequested += (s, e) => CloseInteractionDetail();
            panel.Dock = DockStyle.Fill;

            pnlInteractionDetailContainer.Controls.Add(panel);

            pnlListContainer.Visible = false;
            pnlEditContainer.Visible = false;
            pnlDetailContainer.Visible = false;
            pnlInteractionDetailContainer.Visible = true;
            pnlInteractionDetailContainer.BringToFront();
        }

        public void CloseInteractionDetail()
        {
            pnlInteractionDetailContainer.Visible = false;

            if (_activeCustomerId > 0)
                OpenDetailView(_activeCustomerId, "interactions");
        }

        private void ShowListView()
        {
            pnlEditContainer.Visible = false;
            pnlListContainer.Visible = true;
            pnlListContainer.BringToFront();
        }

        // ============================================
        // DATA LOADING
        // ============================================
        private void ApplyPermissionGates()
        {
            var user = SessionManager.CurrentUser;

            // Create Customer: Admin + Crew only
            bool canCreate = user?.IsAdmin == true || user?.IsCrew == true;

            if (fabNew != null)
            {
                fabNew.Visible = canCreate;
                if (canCreate && fabNew.Parent != null)
                    fabNew.BringToFront();
            }
        }

        private void UpdateButtonsState()
        {
            // No-op - toolbar removed. Actions handled by card click + FAB.
        }

        private async Task LoadDataAsync()
        {
            string? customerType = cmbType.SelectedIndex switch
            {
                1 => "Individual",
                2 => "Business",
                _ => null
            };

            bool? isActive = cmbActive.SelectedIndex switch
            {
                1 => true,
                2 => false,
                _ => null
            };

            var response = await _customerService.GetCustomersAsync(
                page: 1,
                pageSize: 10000,
                search: string.IsNullOrWhiteSpace(txtSearch.Text) ? null : txtSearch.Text,
                customerType: customerType,
                isActive: isActive,
                includeArchived: chkShowArchived.Checked);

            RenderCustomerCards(response.Data);

            

            UpdateButtonsState();
        }

        private void RenderCustomerCards(System.Collections.Generic.List<CustomerModel> customers)
        {
            pnlCards.SuspendLayout();
            pnlCards.Controls.Clear();

            if (customers == null || customers.Count == 0)
            {
                var empty = new Label
                {
                    Text = "No customers found.",
                    Font = Typography.Body,
                    ForeColor = Colors.TextMuted,
                    AutoSize = false,
                    Height = 100,
                    Width = 400,
                    TextAlign = System.Drawing.ContentAlignment.MiddleCenter,
                    Margin = new Padding(0, 40, 0, 0)
                };
                pnlCards.Controls.Add(empty);
                pnlCards.ResumeLayout();
                return;
            }

            int cardWidth = GetCardWidth();

            foreach (var c in customers)
            {
                var card = new CustomerCard
                {
                    CustomerId   = c.CustomerId,
                    CustomerName = c.FullName ?? "",
                    Email        = c.Email ?? "",
                    Phone        = c.PhonePrimary ?? "",
                    CustomerType = c.CustomerType ?? "Individual",
                    CustomerCode = c.CustomerCode ?? "",
                    IsActive     = c.IsActive,
                    IsArchived   = c.IsArchived,
                    Width        = cardWidth
                };
                card.Click += (s, e) => OpenDetailView(card.CustomerId);
                pnlCards.Controls.Add(card);
            }

            pnlCards.ResumeLayout();
        }

        private int GetCardWidth()
        {
            return pnlCards.ClientSize.Width
                   - pnlCards.Padding.Left
                   - pnlCards.Padding.Right
                   - SystemInformation.VerticalScrollBarWidth
                   - 4;
        }

        private void ResizeCards()
        {
            int w = GetCardWidth();
            foreach (Control ctrl in pnlCards.Controls)
            {
                if (ctrl is CustomerCard)
                    ctrl.Width = w;
            }
        }
        private async Task SearchAsync()
        {
            
            await LoadDataAsync();
        }

        

