        private void EditSelected()
        {
            var customerId = GetSelectedCustomerId();
            if (customerId == 0) return;
            OpenEditView(customerId);
        }

        private async Task DeleteSelectedAsync()
        {
            var customerId = GetSelectedCustomerId();
            if (customerId == 0) return;

            var name = "selected customer"; // card-based UI - name resolved per customer

            var confirm = MessageBox.Show(
                $"Deactivate customer '{name}'?\n\nExisting data will be preserved.",
                "Confirm Deactivate",
                MessageBoxButtons.YesNo,
                MessageBoxIcon.Warning);

            if (confirm != DialogResult.Yes) return;

            var (success, error) = await _customerService.DeleteCustomerAsync(customerId);
            if (success)
            {
                MessageBox.Show("Customer deactivated.", "Success",
                    MessageBoxButtons.OK, MessageBoxIcon.Information);
                await LoadDataAsync();
            }
            else
            {
                MessageBox.Show($"Failed: {error}", "Error",
                    MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }
